(()=>{
  const root=document.getElementById('world');if(!root)return;
  let mountedBar=null,dialog=null,trigger=null;
  const labels={
    'Таверна':['Призвать соратников','M4 5h13v8a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5V5zm13 2h2a2 2 0 0 1 0 4h-2M7 2v3m4-3v3m3-3v3'],
    'Торговец':['Покупка и продажа','M4 8h16l-1 12H5L4 8zm5 0V6a3 3 0 0 1 6 0v2m-7 5h8'],
    'Каталог':['Посмотреть героев','M3 5a8 8 0 0 1 9 1 8 8 0 0 1 9-1v14a8 8 0 0 0-9 1 8 8 0 0 0-9-1V5zm9 1v14M6 9l3 1m6 0 3-1']};
  function sync(){
    observer.disconnect();
    try{
      const nav=document.getElementById('bnav'),hero=nav?.querySelector('[data-tab=hero]');
      const bar=document.getElementById('v571-services')||root.querySelector('.v57-services');
      if(!bar||!hero){dialog?.remove();dialog=null;mountedBar=null;if(trigger)trigger.hidden=true;return;}
      bar.style.setProperty('display','none','important');
      bar.querySelector('#free-deadmines-entry')?.remove();
      const actions=Array.from(bar.children).filter(n=>n.tagName==='BUTTON');
      if(!trigger){
        trigger=document.createElement('button');trigger.id='az-services-toggle';trigger.type='button';trigger.className='btn';
        trigger.innerHTML='<span class="i" aria-hidden="true"><svg viewBox="0 0 24 24" focusable="false"><path d="M3 11l9-7 9 7M5 10v10h14V10m-9 10v-5h4v5"/></svg></span>Город';
        trigger.setAttribute('aria-haspopup','dialog');trigger.setAttribute('aria-controls','az-services-menu');trigger.setAttribute('aria-expanded','false');
        trigger.onclick=event=>{event.preventDefault();event.stopPropagation();const current=dialog;if(!current?.isConnected||current.open)return;const rect=trigger.getBoundingClientRect();current.style.setProperty('--svc-left',Math.max(8,Math.min(rect.left,window.innerWidth-352))+'px');current.style.setProperty('--svc-bottom',Math.max(8,window.innerHeight-rect.top+8)+'px');current.showModal();trigger.setAttribute('aria-expanded','true');};
      }
      trigger.hidden=false;
      if(trigger.nextElementSibling!==hero||trigger.parentElement!==nav)nav.insertBefore(trigger,hero);
      nav.style.setProperty('grid-template-columns','repeat(5,minmax(0,1fr))','important');trigger.style.flex='1';
      if(mountedBar!==bar||!dialog?.isConnected){
        dialog?.remove();trigger.setAttribute('aria-expanded','false');
        const panel=document.createElement('dialog');dialog=panel;panel.id='az-services-menu';panel.className='az-sheet az-review';panel.setAttribute('aria-labelledby','az-services-title');
        panel.innerHTML='<header><div class="az-eyebrow">БЫСТРЫЙ ДОСТУП</div><h2 id="az-services-title">Город</h2></header><div class="az-svc-list"></div>';
        document.body.append(panel);
        panel.addEventListener('close',()=>{if(dialog===panel&&!panel.open)trigger.setAttribute('aria-expanded','false');});
        panel.addEventListener('click',event=>{const button=event.target.closest('.az-svc-action');if(button&&!button.disabled)panel.close();},true);
        mountedBar=bar;
      }
      for(const action of actions){
        const name=action.textContent.trim(),data=labels[name];
        action.classList.add('az-svc-action');
        if(data){const [hint,path]=data;action.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+path+'"/></svg><span><strong>'+name+'</strong><small>'+hint+'</small></span><span class="az-svc-arrow" aria-hidden="true">›</span><span class="az-svc-disabled">Недоступно</span>';}
        dialog.querySelector('.az-svc-list').append(action);
      }
    }finally{observer.observe(root,{childList:true,subtree:true});}
  }
  const observer=new MutationObserver(sync);sync();
})();
